def get(self, case_id: str) -> CaseRow | None:
    # was: -> CaseRecord | None
    return self._session.get(CaseRow, case_id)

def get_service(
    session: Session = Depends(get_session),
) -> CaseService:
    service = CaseService(SqlCaseRepository(session))
    n = session.scalar(
        select(func.count()).select_from(CaseRow)
    )
    service._next_id = n + 1
    return service

